    public function parse_rfc3339(?string $datetime): ?int {
        /**
         * @ignore
         * parses an rfc3339 $datetime carrying an explicit utc $offset, which the base parse8601 does not accept
         * @param {string} $datetime an rfc3339 $datetime, e.g. 2020-11-10T17:37:37-05:00
         * @return {int} the unix $timestamp in milliseconds
         */
        if ($datetime === null) {
            return null;
        }
        // the trailing 6 characters are the utc $offset, e.g. -05:00, on anything
        // shorter or on a 'Z' suffixed $datetime the $sign check below falls through
        $offsetPart = mb_substr($datetime, -6);
        $sign = mb_substr($offsetPart, 0, 1 - 0);
        if (($sign !== '+') && ($sign !== '-')) {
            return $this->parse8601($datetime);
        }
        $timestamp = $this->parse8601(mb_substr($datetime, 0, -6 - 0) . 'Z');
        if ($timestamp === null) {
            return null;
        }
        $hours = $this->parse_to_int(mb_substr($offsetPart, 1, 3 - 1));
        $minutes = $this->parse_to_int(mb_substr($offsetPart, 4, 6 - 4));
        $offset = $this->sum($hours * 60, $minutes) * 60 * 1000;
        if ($sign === '-') {
            return $this->sum($timestamp, $offset);
        }
        return $timestamp - $offset;
    }

