    private function do_fetch_markets($params = array()) {
        /**
         * retrieves data on all us stock tickers covered by massive
         *
         * @see https://massive.com/docs/rest/stocks/tickers/all-tickers
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->market] the asset class to load, defaults to 'stocks'
         * @param {boolean} [$params->active] whether to load only actively traded tickers, defaults to true
         * @param {string} [$params->date] load the ticker universe stood on this date, e.g. 2026-08-28
         * @return {array[]} an array of objects representing market data
         */
        $options = $this->safe_dict($this->options, 'fetchMarkets', array());
        $request = array(
            'market' => $this->safe_string($options, 'market', 'stocks'),
            'active' => $this->safe_bool($options, 'active', true),
            'limit' => $this->safe_integer($options, 'limit', 1000),
        );
        $maxPages = $this->safe_integer($options, 'maxPages', 30);
        $result = array();
        for ($i = 0; $i < $maxPages; $i++) {
            $response = Async\await($this->publicGetV3ReferenceTickers($this->extend($request, $params)));
            //
            //     {
            //         "results" => array(
            //             {
            //                 "ticker" => "AAPL",
            //                 "name" => "Apple Inc.",
            //                 "market" => "stocks",
            //                 "locale" => "us",
            //                 "primary_exchange" => "XNAS",
            //                 "type" => "CS",
            //                 "active" => true,
            //                 "currency_name" => "usd",
            //                 "cik" => "0000320193",
            //                 "composite_figi" => "BBG000B9XRY4",
            //                 "share_class_figi" => "BBG001S5N8V8",
            //                 "last_updated_utc" => "2026-08-29T06:10:48.224862169Z"
            //             }
            //         ),
            //         "status" => "OK",
            //         "request_id" => "c7fa5b578083aeb23c5542e15efe7b14",
            //         "count" => 1,
            //         "next_url" => "https://api.massive.com/v3/reference/tickers?cursor=YWN0aXZl"
            //     }
            //
            $results = $this->safe_list($response, 'results', array());
            $resultsLength = count($results);
            if ($resultsLength === 0) {
                break;
            }
            $result = $this->array_concat($result, $results);
            $nextUrl = $this->safe_string($response, 'next_url');
            if ($nextUrl === null) {
                break;
            }
            $parts = explode('cursor=', $nextUrl);
            $partsLength = count($parts);
            if ($partsLength < 2) {
                break;
            }
            $request['cursor'] = $parts[1];
        }
        return $this->parse_markets($result);
    }

    public function parse_market(array $market): array {
        $id = $this->safe_string($market, 'ticker');
        // a stock ticker is not a currency code, it must not go through
        // safeCurrencyCode - tickers such, COMP or UNI would be rewritten
        $base = $id;
        $quoteId = $this->safe_string($market, 'currency_name', 'usd');
        $quote = strtoupper($quoteId);
        $symbol = $base . '/' . $quote;
        return $this->safe_market_structure(array(
            'id' => $id,
            'symbol' => $symbol,
            'base' => $base,
            'quote' => $quote,
            'baseId' => $id,
            'quoteId' => $quoteId,
            'settle' => null,
            'settleId' => null,
            'type' => 'spot',
            'spot' => true,
            'stock' => true,
            'margin' => false,
            'swap' => false,
            'future' => false,
            'option' => false,
            'active' => $this->safe_bool($market, 'active'),
            'contract' => false,
            'linear' => null,
            'inverse' => null,
            'taker' => 0,
            'maker' => 0,
            'contractSize' => null,
            'expiry' => null,
            'expiryDatetime' => null,
            'strike' => null,
            'optionType' => null,
            'precision' => array(
