    private function do_fetch_status($params = array()) {
        /**
         * the latest known information on the availability of the us equity market
         *
         * @see https://massive.com/docs/rest/stocks/market-operations/market-status
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [status structure](https://docs.ccxt.com/#/?id=exchange-status-structure), the raw session state stays under `info`, e.g. `info.market` is one of open, closed, extended-hours
         */
        $response = Async\await($this->publicGetV1MarketstatusNow($params));
        //
        //     {
        //         "afterHours" => false,
        //         "currencies" => array( "crypto" => "open", "fx" => "closed" ),
        //         "earlyHours" => false,
        //         "exchanges" => array( "nasdaq" => "closed", "nyse" => "closed", "otc" => "closed" ),
        //         "market" => "closed",
        //         "serverTime" => "2026-08-29T22:03:43-04:00"
        //     }
        //
        $updated = $this->parse_rfc3339($this->safe_string($response, 'serverTime'));
        return array(
            'status' => 'ok',
            'updated' => $updated,
            'eta' => null,
            'url' => null,
            'info' => $response,
        );
    }

