         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->method] 'snapshot' (default) or 'previousDayBar', snapshots need a snapshot entitlement on the massive plan
         * @return {array} a [ticker structure](https://docs.ccxt.com/#/?id=ticker-structure)
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'stocksTicker' => $market['id'],
        );
        $method = null;
        list($method, $params) = $this->handle_option_and_params($params, 'fetchTicker', 'method', 'snapshot');
        if ($method === 'previousDayBar') {
            $previous = Async\await($this->publicGetV2AggsTickerStocksTickerPrev($this->extend($request, $params)));
            //
            //     {
            //         "ticker" => "AAPL",
            //         "queryCount" => 1,
            //         "resultsCount" => 1,
            //         "adjusted" => true,
            //         "results" => array(
            //             {
            //                 "T" => "AAPL",
            //                 "v" => 38649398,
            //                 "vw" => 319.5134,
            //                 "o" => 316.845,
            //                 "c" => 319.7,
            //                 "h" => 322.37,
            //                 "l" => 315.4504,
            //                 "t" => 1787947200000,
            //                 "n" => 760062
            //             }
            //         ),
            //         "status" => "OK"
            //     }
            //
            $previousResults = $this->safe_list($previous, 'results', array());
            return $this->parse_ticker($this->safe_dict($previousResults, 0, array()), $market);
        }
        $response = Async\await($this->publicGetV2SnapshotLocaleUsMarketsStocksTickersStocksTicker($this->extend($request, $params)));
        //
        //     {
        //         "request_id" => "657e430f1ae768891f018e08e03598d8",
        //         "status" => "OK",
        //         "ticker" => {
        //             "ticker" => "AAPL",
