        //             "min" => array( "av" => 28724441, "c" => 120.4201, "h" => 120.468, "l" => 120.37, "n" => 762, "o" => 120.435, "t" => 1684428720000, "v" => 270796, "vw" => 120.4129 ),
        //             "prevDay" => array( "o" => 117.19, "h" => 119.63, "l" => 116.44, "c" => 119.49, "v" => 110597265, "vw" => 118.4998 ),
        //             "todaysChange" => 0.98,
