    private function do_fetch_tickers(?array $symbols = null, $params = array()) {
        /**
         * fetches price $tickers for multiple markets, statistical information calculated over the past 24 hours for each market
         *
         * @see https://massive.com/docs/rest/stocks/snapshots/full-market-snapshot
         * @see https://massive.com/docs/rest/stocks/aggregates/daily-market-summary
         *
         * @param {string[]} [$symbols] unified $symbols of the markets to fetch the ticker for, all market $tickers are returned if not assigned
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {string} [$params->method] 'snapshot' (default) or 'groupedDailyBars', snapshots need a snapshot entitlement on the massive plan
         * @param {string} [$params->date] only read by 'groupedDailyBars', the trading day to summarise, e.g. 2026-08-28, defaults to today
         * @return {array} a dictionary of [ticker structures](https://docs.ccxt.com/#/?id=ticker-structure)
         */
        Async\await($this->load_markets());
        $symbols = $this->market_symbols($symbols);
        $method = null;
        list($method, $params) = $this->handle_option_and_params($params, 'fetchTickers', 'method', 'snapshot');
        if ($method === 'groupedDailyBars') {
            $groupedRequest = array(
                'date' => $this->safe_string($params, 'date', $this->yyyymmdd($this->milliseconds())),
            );
            $params = $this->omit($params, array( 'date' ));
            $grouped = Async\await($this->publicGetV2AggsGroupedLocaleUsMarketStocksDate($this->extend($groupedRequest, $params)));
            //
            //     {
            //         "queryCount" => 12518,
            //         "resultsCount" => 12518,
            //         "adjusted" => true,
            //         "results" => array(
            //             array( "T" => "GBCI", "v" => 898130, "vw" => 46.9919, "o" => 47.5, "c" => 46.88, "h" => 47.71, "l" => 46.85, "t" => 1787947200000, "n" => 16823 )
            //         ),
            //         "status" => "OK"
            //     }
            //
            $groupedResults = $this->safe_list($grouped, 'results', array());
            return $this->parse_tickers($groupedResults, $symbols);
        }
        $request = array();
        if ($symbols !== null) {
            $ids = $this->market_ids($symbols);
            $request['tickers'] = implode(',', $ids);
        }
        $response = Async\await($this->publicGetV2SnapshotLocaleUsMarketsStocksTickers($this->extend($request, $params)));
        //
        //     {
        //         "count" => 1,
        //         "status" => "OK",
        //         "tickers" => array(
        //             {
        //                 "ticker" => "BCAT",
        //                 "day" => array( "o" => 20.64, "h" => 20.64, "l" => 20.506, "c" => 20.506, "v" => 37216, "vw" => 20.616 ),
        //                 "prevDay" => array( "o" => 20.79, "h" => 21, "l" => 20.5, "c" => 20.63, "v" => 292738, "vw" => 20.6939 ),
        //                 "lastQuote" => array( "p" => 20.5, "s" => 13, "P" => 20.6, "S" => 22, "t" => 1605192959994246100 ),
        //                 "lastTrade" => array( "p" => 20.506, "s" => 2416, "x" => 4, "t" => 1605192894630916600, "i" => "71675577320245" ),
        //                 "todaysChange" => -0.124,
        //                 "todaysChangePerc" => -0.601,
        //                 "updated" => 1605192894630916600
        //             }
        //         )
        //     }
        //
        $tickers = $this->safe_list($response, 'tickers', array());
        return $this->parse_tickers($tickers, $symbols);
    }

    public function parse_ticker(array $ticker, ?array $market = null): array {
        $day = $this->safe_dict($ticker, 'day');
        if ($day === null) {
            // aggregate bar shape, returned by the previous $day bar and the daily $market summary endpoints
            $barMarketId = $this->safe_string($ticker, 'T');
            $barTimestamp = $this->safe_integer($ticker, 't');
            $barClose = $this->safe_string($ticker, 'c');
            return $this->safe_ticker(array(
                'symbol' => $this->safe_symbol($barMarketId, $market),
                'timestamp' => $barTimestamp,
                'datetime' => $this->iso8601($barTimestamp),
                'high' => $this->safe_string($ticker, 'h'),
                'low' => $this->safe_string($ticker, 'l'),
                'bid' => null,
                'bidVolume' => null,
                'ask' => null,
                'askVolume' => null,
                'vwap' => $this->safe_string($ticker, 'vw'),
                'open' => $this->safe_string($ticker, 'o'),
                'close' => $barClose,
                'last' => $barClose,
                'previousClose' => null,
                'change' => null,
                'percentage' => null,
                'average' => null,
                'baseVolume' => $this->safe_string($ticker, 'v'),
                'quoteVolume' => null,
                'info' => $ticker,
            ), $market);
        }
        // snapshot shape
        $marketId = $this->safe_string($ticker, 'ticker');
        $lastQuote = $this->safe_dict($ticker, 'lastQuote', array());
        $lastTrade = $this->safe_dict($ticker, 'lastTrade', array());
        $previousDay = $this->safe_dict($ticker, 'prevDay', array());
        $timestamp = $this->safe_integer_product($ticker, 'updated', 0.000001);
        $last = $this->safe_string($lastTrade, 'p');
        return $this->safe_ticker(array(
            'symbol' => $this->safe_symbol($marketId, $market),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'high' => $this->safe_string($day, 'h'),
            'low' => $this->safe_string($day, 'l'),
            'bid' => $this->safe_string($lastQuote, 'p'),
            'bidVolume' => $this->safe_string($lastQuote, 's'),
            'ask' => $this->safe_string($lastQuote, 'P'),
            'askVolume' => $this->safe_string($lastQuote, 'S'),
            'vwap' => $this->safe_string($day, 'vw'),
            'open' => $this->safe_string($day, 'o'),
            'close' => $this->safe_string($day, 'c'),
            'last' => $last,
            'previousClose' => $this->safe_string($previousDay, 'c'),
            'change' => $this->safe_string($ticker, 'todaysChange'),
            'percentage' => $this->safe_string($ticker, 'todaysChangePerc'),
            'average' => null,
            'baseVolume' => $this->safe_string($day, 'v'),
            'quoteVolume' => null,
            'info' => $ticker,
        ), $market);
    }

    public function fetch_ohlcv(string $symbol, $timeframe = '1d', ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_ohlcv(...))($symbol, $timeframe, $since, $limit, $params);
    }

    private function do_fetch_ohlcv(string $symbol, $timeframe = '1d', ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches historical candlestick data containing $the open, high, low, and close price, and $the volume of a $market
         *
         * @see https://massive.com/docs/rest/stocks/aggregates/custom-bars
         *
         * @param {string} $symbol unified $symbol of $the $market to fetch OHLCV data for
         * @param {string} $timeframe $the length of time each candle represents
         * @param {int} [$since] timestamp in ms of $the earliest candle to fetch
         * @param {int} [$limit] $the maximum amount of candles to fetch, max 50000
         * @param {array} [$params] extra parameters specific to $the exchange API endpoint
         * @param {int} [$params->until] timestamp in ms of $the latest candle to fetch
         * @param {boolean} [$params->adjusted] whether $the bars are adjusted for splits, defaults to true
         * @return {int[][]} A list of candles ordered, open, high, low, close, volume
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $selectedTimeframe = $this->safe_string($this->timeframes, $timeframe, $timeframe);
        $parts = explode('/', $selectedTimeframe);
        $partsLength = count($parts);
        if ($partsLength < 2) {
            throw new BadRequest($this->id . ' fetchOHLCV() does not support $the ' . $timeframe . ' timeframe');
        }
        $maxLimit = $this->safe_integer($this->options, 'maxOHLCVLimit', 50000);
        if ($limit === null) {
            $limit = $this->safe_integer($this->options, 'defaultLimit', 1000);
        }
        $limit = min($limit, $maxLimit);
        $until = $this->safe_integer($params, 'until');
        $params = $this->omit($params, array( 'until' ));
        $now = $this->milliseconds();
        $duration = $this->parse_timeframe($timeframe) * 1000;
        $sort = 'asc';
        if ($since === null) {
            // ask for $the most recent candles instead of $the oldest ones inside $the window.
            // us equities trade ~6.5 hours a day, 5 days a week, so a window `$limit` candles
            // wide in wall clock time always comes back short - widen it and $the exchange
            // cut it down to `$limit`, parseOHLCVs sorts $the result back into ascending order
            $sort = 'desc';
            if ($until === null) {
                $until = $now;
            }
            $windowFactor = $this->safe_integer($this->options, 'ohlcvWindowFactor', 10);
            $since = $until - ($limit * $duration * $windowFactor);
            if ($since < 0) {
                $since = 0;
            }
        } elseif ($until === null) {
            $computedUntil = $this->sum($since, $limit * $duration);
            if ($computedUntil > $now) {
                $until = $now;
            } else {
                $until = $computedUntil;
            }
        }
        // massive counts `$limit` in base aggregates - seconds for $the second $timespan,
        // minutes for minute and hour, days for day and everything above it - and not in
        // returned candles, so a weekly $request for 3 candles comes back with a single one
        $timespan = $parts[1];
        $baseDuration = 24 * 60 * 60 * 1000;
        if ($timespan === 'second') {
            $baseDuration = 1000;
        } elseif (($timespan === 'minute') || ($timespan === 'hour')) {
            $baseDuration = 60 * 1000;
        }
        $requestLimit = $this->parse_to_int($limit * $duration / $baseDuration);
        $requestLimit = min($requestLimit, $maxLimit);
        $request = array(
            'stocksTicker' => $market['id'],
            'multiplier' => $parts[0],
            'timespan' => $parts[1],
            'from' => $since,
            'to' => $until,
            'limit' => $requestLimit,
            'sort' => $sort,
            'adjusted' => true,
        );
        $response = Async\await($this->publicGetV2AggsTickerStocksTickerRangeMultiplierTimespanFromTo($this->extend($request, $params)));
        //
        //     {
        //         "ticker" => "AAPL",
        //         "queryCount" => 3,
        //         "resultsCount" => 3,
        //         "adjusted" => true,
        //         "results" => array(
        //             array( "v" => 75051951, "vw" => 305.1311, "o" => 309.58, "c" => 303.42, "h" => 311.8, "l" => 302.56, "t" => 1785729600000, "n" => 1388685 )
        //         ),
        //         "status" => "OK"
        //     }
        //
        $results = $this->safe_list($response, 'results', array());
        // when no `$since` was given $the newest candles are $the interesting ones, so trim
        // $the over-fetched $tail-end of $the window from $the front instead of from $the back
        $tail = ($sort === 'desc');
        return $this->parse_ohlcvs($results, $market, $timeframe, $since, $limit, $tail);
    }

    public function parse_ohlcv(mixed $ohlcv, ?array $market = null): array {
        return array(
            $this->safe_integer($ohlcv, 't'),
            $this->safe_number($ohlcv, 'o'),
            $this->safe_number($ohlcv, 'h'),
            $this->safe_number($ohlcv, 'l'),
            $this->safe_number($ohlcv, 'c'),
            $this->safe_number($ohlcv, 'v'),
        );
    }

    public function fetch_trades(string $symbol, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_trades(...))($symbol, $since, $limit, $params);
    }

    private function do_fetch_trades(string $symbol, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * get the list of most recent trades for a particular $symbol
         *
         * @see https://massive.com/docs/rest/stocks/trades-quotes/trades
         *
         * @param {string} $symbol unified $symbol of the $market to fetch trades for
         * @param {int} [$since] timestamp in ms of the earliest trade to fetch
         * @param {int} [$limit] the maximum amount of trades to fetch, max 50000
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->until] timestamp in ms of the latest trade to fetch
         * @return {array[]} a list of [trade structures](https://docs.ccxt.com/#/?id=public-trades)
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'stocksTicker' => $market['id'],
            'sort' => 'timestamp',
            'order' => 'desc',
        );
        if ($limit !== null) {
            $maxLimit = $this->safe_integer($this->options, 'maxTradesLimit', 50000);
            $request['limit'] = min($limit, $maxLimit);
        }
        if ($since !== null) {
            // the api works in nanoseconds, which overflows a double, keep it a string
            $request['timestamp.gte'] = Precise::string_mul($this->number_to_string($since), '1000000');
            $request['order'] = 'asc';
        }
        $until = $this->safe_integer($params, 'until');
        $params = $this->omit($params, array( 'until' ));
        if ($until !== null) {
            $request['timestamp.lte'] = Precise::string_mul($this->number_to_string($until), '1000000');
        }
        $response = Async\await($this->publicGetV3TradesStocksTicker($this->extend($request, $params)));
        //
        //     {
        //         "request_id" => "a47d1beb8c11b6ae897ab76cdbbf35a3",
        //         "status" => "OK",
        //         "results" => array(
        //             {
        //                 "id" => "1",
        //                 "exchange" => 11,
        //                 "tape" => 3,
        //                 "price" => 171.55,
        //                 "size" => 100,
        //                 "conditions" => array( 12, 41 ),
        //                 "correction" => 0,
        //                 "sequence_number" => 1063,
        //                 "participant_timestamp" => 1517562000015577000,
        //                 "sip_timestamp" => 1517562000016036600
        //             }
        //         )
        //     }
        //
        $results = $this->safe_list($response, 'results', array());
        return $this->parse_trades($results, $market, $since, $limit);
    }

    public function parse_trade(array $trade, ?array $market = null): array {
        $marketId = $this->safe_string($trade, 'T');
        $resolved = $this->safe_market($marketId, $market);
        $timestamp = $this->safe_integer_product_2($trade, 'sip_timestamp', 'participant_timestamp', 0.000001);
        return $this->safe_trade(array(
            'id' => $this->safe_string_2($trade, 'id', 'i'),
            'info' => $trade,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'symbol' => $resolved['symbol'],
            'order' => null,
            'type' => null,
            // the consolidated tape does not disclose the aggressor of a $trade
            'side' => null,
            'takerOrMaker' => null,
            'price' => $this->safe_string_2($trade, 'price', 'p'),
            'amount' => $this->safe_string_2($trade, 'size', 's'),
            'cost' => null,
            'fee' => null,
        ), $resolved);
    }

    public function fetch_order_book(string $symbol, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_order_book(...))($symbol, $limit, $params);
    }

    private function do_fetch_order_book(string $symbol, ?int $limit = null, $params = array()) {
        /**
         * fetches the top of the consolidated order book, massive publishes the national best bid and offer, not the full depth of book
         *
         * @see https://massive.com/docs/rest/stocks/trades-quotes/last-quote
         *
         * @param {string} $symbol unified $symbol of the $market to fetch the order book for
         * @param {int} [$limit] not used by massive.fetchOrderBook, the nbbo carries a single level per side
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} A dictionary of [order book structures](https://docs.ccxt.com/#/?id=order-book-structure) indexed by $market symbols
         */
        Async\await($this->load_markets());
        $market = $this->market($symbol);
        $request = array(
            'stocksTicker' => $market['id'],
        );
        $response = Async\await($this->publicGetV2LastNbboStocksTicker($this->extend($request, $params)));
        //
        //     {
        //         "request_id" => "b84e24636301f19f88e0dfbf9a45ed5c",
        //         "status" => "OK",
        //         "results" => {
        //             "P" => 127.98,
        //             "S" => 7,
        //             "T" => "AAPL",
        //             "X" => 19,
        //             "p" => 127.96,
        //             "q" => 83480742,
        //             "s" => 1,
        //             "t" => 1617827221349730300,
        //             "x" => 11,
        //             "y" => 1617827221349366000,
        //             "z" => 3
        //         }
        //     }
        //
        $result = $this->safe_dict($response, 'results', array());
        $timestamp = $this->safe_integer_product($result, 't', 0.000001);
        $bids = array();
        $asks = array();
        $bidPrice = $this->safe_string($result, 'p');
        $bidAmount = $this->safe_string($result, 's');
        if (($bidPrice !== null) && Precise::string_gt($bidPrice, '0')) {
            $bids[] = array( $bidPrice, $bidAmount );
        }
        $askPrice = $this->safe_string($result, 'P');
        $askAmount = $this->safe_string($result, 'S');
        if (($askPrice !== null) && Precise::string_gt($askPrice, '0')) {
            $asks[] = array( $askPrice, $askAmount );
        }
        $rawOrderBook = array(
            'bids' => $bids,
            'asks' => $asks,
        );
        $orderbook = $this->parse_order_book($rawOrderBook, $market['symbol'], $timestamp);
        $orderbook['nonce'] = $this->safe_integer($result, 'q');
        return $orderbook;
    }

    public function sign(mixed $path, mixed $api = 'public', $method = 'GET', $params = array(), ?array $headers = null, ?string $body = null) {
        // every massive endpoint is authenticated, the $api key entitles the
        // caller to a data feed, it is not bound to a trading account
        $this->check_required_credentials();
        $request = '/' . $this->implode_params($path, $params);
        $url = $this->implode_hostname($this->urls['api']['public']) . $request;
        $query = $this->omit($params, $this->extract_params($path));
        $queryLength = count($query);
        if ($queryLength > 0) {
            $url .= '?' . $this->urlencode($query);
        }
        $headers = array(
            'Authorization' => 'Bearer ' . $this->apiKey,
            'Accept' => 'application/json',
        );
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $headers );
    }

    public function handle_errors(int $code, string $reason, string $url, string $method, array $headers, string $body, mixed $response, mixed $requestHeaders, mixed $requestBody) {
        if ($response === null) {
            return null; // fallback to the default $error handler
        }
        $status = $this->safe_string($response, 'status');
        // DELAYED is a successful $response on the delayed data plans
        if (($status === 'OK') || ($status === 'DELAYED')) {
            return null;
        }
        $error = $this->safe_string_2($response, 'error', 'message');
        if (($status === null) && ($error === null)) {
            return null;
        }
        //
        //     array( "status" => "NOT_AUTHORIZED", "request_id" => "943c", "message" => "You are not entitled to this data." )
        //     array( "status" => "ERROR", "request_id" => "943c", "error" => "Unknown API Key" )
        //
        $feedback = $this->id . ' ' . $body;
        $this->throw_exactly_matched_exception($this->exceptions['exact'], $error, $feedback);
        $this->throw_broadly_matched_exception($this->exceptions['broad'], $error, $feedback);
        $this->throw_exactly_matched_exception($this->exceptions['exact'], $status, $feedback);
        throw new ExchangeError($feedback);
    }
}
